class SalaryHistory(private val tz: TimeZone = TimeZone.currentSystemDefault()) {
    private val byStart = sortedMapOf<LocalDate, Money>()        // java.util.TreeMap

    fun salaryAt(when: LocalDate = Clock.System.todayIn(tz)): Money =
        byStart.floorEntry(when)?.value                         // latest start <= when
            ?: error("no salary effective on $when")

    fun setSalary(amount: Money, from: LocalDate = Clock.System.todayIn(tz)) {
        byStart[from] = amount
    }
}
